#!/usr/bin/env bash
# Renders the hardened k3s configuration shared by dev (podman) and test/prod
# (hosts). Based on the k3s CIS hardening guide; one template for all
# environments so dev exercises the same flags as prod.
# shellcheck shell=bash

K3S_HARDENING_DIR="/etc/rancher/k3s/hardening"
K3S_AUDIT_LOG_DIR="/var/log/kubernetes/audit"

# render_k3s_server_config <node-name> <cluster-init:true|false> <tls-san-csv> [server-url]
render_k3s_server_config() {
  local node="$1" init="$2" sans="$3" server_url="${4:-}"
  local san
  cat <<CFG
# generated by scripts/lib/k3s-config.sh — do not edit on the node
node-name: "${node}"
write-kubeconfig-mode: "0600"
tls-san:
CFG
  IFS=',' read -ra _sans <<<"$sans"
  for san in "${_sans[@]}"; do printf '  - "%s"\n' "$san"; done
  if [[ "$init" == "true" ]]; then echo 'cluster-init: true'; fi
  if [[ -n "$server_url" ]]; then printf 'server: "%s"\n' "$server_url"; fi
  # embedded etcd (HA servers): scheduled, compressed snapshots on every server
  # (/var/lib/rancher/k3s/server/db/snapshots). Optional copy to an S3 target
  # OUTSIDE this cluster: K3S_ETCD_S3_CONFIG_SECRET = Secret in kube-system with
  # the etcd-s3 settings (k3s --etcd-s3-config-secret). Snapshots contain the
  # datastore incl. encrypted Secrets; restoring needs the server token.
  if [[ "$init" == "true" || -n "$server_url" ]]; then
    printf 'etcd-snapshot-schedule-cron: "%s"\n' "${K3S_ETCD_SNAPSHOT_CRON:-0 */6 * * *}"
    printf 'etcd-snapshot-retention: %s\n' "${K3S_ETCD_SNAPSHOT_RETENTION:-28}"
    echo 'etcd-snapshot-compress: true'
    if [[ -n "${K3S_ETCD_S3_CONFIG_SECRET:-}" ]]; then
      echo 'etcd-s3: true'
      printf 'etcd-s3-config-secret: "%s"\n' "$K3S_ETCD_S3_CONFIG_SECRET"
    fi
  fi
  cat <<CFG
# --- CIS / hardening ----------------------------------------------------------
secrets-encryption: true
protect-kernel-defaults: true
# no cloud provider on-prem
disable-cloud-controller: true
# air-gap: never fall back to the upstream registry when the mirror misses
disable-default-registry-endpoint: true
kube-apiserver-arg:
  - "enable-admission-plugins=NodeRestriction,EventRateLimit"
  - "admission-control-config-file=${K3S_HARDENING_DIR}/admission.yaml"
  - "audit-policy-file=${K3S_HARDENING_DIR}/audit-policy.yaml"
  - "audit-log-path=${K3S_AUDIT_LOG_DIR}/audit.log"
  - "audit-log-format=json"
  - "audit-log-maxage=30"
  - "audit-log-maxbackup=10"
  - "audit-log-maxsize=100"
  - "request-timeout=300s"
  - "tls-min-version=VersionTLS12"
  - "tls-cipher-suites=TLS_ECDHE_ECDSA_WITH_AES_128_GCM_SHA256,TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256,TLS_ECDHE_ECDSA_WITH_AES_256_GCM_SHA384,TLS_ECDHE_RSA_WITH_AES_256_GCM_SHA384,TLS_ECDHE_ECDSA_WITH_CHACHA20_POLY1305,TLS_ECDHE_RSA_WITH_CHACHA20_POLY1305"
kube-controller-manager-arg:
  - "terminated-pod-gc-threshold=100"
  - "tls-min-version=VersionTLS12"
kube-scheduler-arg:
  - "tls-min-version=VersionTLS12"
kubelet-arg:
  - "streaming-connection-idle-timeout=5m"
  - "make-iptables-util-chains=true"
  - "tls-min-version=VersionTLS12"
  - "pod-max-pids=4096"
CFG
  _render_extra_kubelet_args
}

# K3S_EXTRA_KUBELET_ARGS (space separated key=value) lets an environment add
# kubelet flags, e.g. dev on a cgroup v1 container host.
_render_extra_kubelet_args() {
  local a
  for a in ${K3S_EXTRA_KUBELET_ARGS:-}; do printf '  - "%s"\n' "$a"; done
}

# render_k3s_agent_config <node-name> <server-url>
render_k3s_agent_config() {
  local node="$1" server_url="$2"
  cat <<CFG
# generated by scripts/lib/k3s-config.sh — do not edit on the node
node-name: "${node}"
server: "${server_url}"
protect-kernel-defaults: true
disable-default-registry-endpoint: true
kubelet-arg:
  - "streaming-connection-idle-timeout=5m"
  - "make-iptables-util-chains=true"
  - "tls-min-version=VersionTLS12"
  - "pod-max-pids=4096"
CFG
  _render_extra_kubelet_args
}

# render_registries_yaml <registry-host:port> <endpoint-url> <ca-file-on-node>
# Every upstream registry is redirected to Zot; the upstream registry name is
# kept as the first path element (Zot repo "quay.io/openbao/openbao").
render_registries_yaml() {
  local reg="$1" endpoint="$2" ca="$3" up
  echo "# generated by scripts/lib/k3s-config.sh"
  echo "mirrors:"
  for up in docker.io ghcr.io quay.io registry.k8s.io; do
    cat <<CFG
  "${up}":
    endpoint:
      - "${endpoint}"
    rewrite:
      "^(.*)\$": "${up}/\$1"
CFG
  done
  cat <<CFG
  "${reg}":
    endpoint:
      - "${endpoint}"
configs:
  "${reg}":
    tls:
      ca_file: "${ca}"
CFG
}

# sysctl settings required by protect-kernel-defaults
k3s_required_sysctls() {
  cat <<'CFG'
vm.panic_on_oom=0
vm.overcommit_memory=1
kernel.panic=10
kernel.panic_on_oops=1
CFG
}
